// Запуск нативных автотестов Eitan на Android по кабелю: node run-android.mjs [--grep "<текст|#hash>"] [--list]
// Только adb (Appium не нужен). Тесты — android/tests/*.test.mjs, строго по одному. Перед каждым тестом приложение перезапускается.
import { readdir, writeFile, mkdir } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { Android } from './android/lib.mjs';

const ROOT = path.dirname(fileURLToPath(import.meta.url));
const args = process.argv.slice(2);
const grep = args.includes('--grep') ? args[args.indexOf('--grep') + 1] : null;

const dir = path.join(ROOT, 'android', 'tests');
const files = (await readdir(dir)).filter((f) => f.endsWith('.test.mjs')).sort();
const tests = [];
for (const f of files) {
  const mod = await import(pathToFileURL(path.join(dir, f)).href);
  if (!grep || mod.name.includes(grep)) tests.push({ file: `android/tests/${f}`, name: mod.name, run: mod.default });
}

if (args.includes('--list') || !tests.length) {
  for (const t of tests) console.log(`${t.file}  —  ${t.name}`);
  if (!tests.length) console.log('Нет тестов по фильтру');
  process.exit(0);
}

const results = [];
const app = await Android.start();
for (const t of tests) {
  const started = Date.now();
  let status = 'passed', error, screenshot;
  try {
    await t.run(app);
  } catch (e) {
    if (e.skip) { status = 'skipped'; error = e.message; }
    else {
      status = 'failed';
      error = e.message;
      screenshot = await app.screenshot(path.basename(t.file, '.test.mjs')).catch(() => undefined);
    }
  }
  const ms = Date.now() - started;
  results.push({ file: t.file, name: t.name, status, ms, error, screenshot });
  console.log(`${status === 'passed' ? 'OK  ' : status === 'skipped' ? 'SKIP' : 'FAIL'} ${t.name} (${(ms / 1000).toFixed(1)} с)${error ? `\n     ${error}` : ''}`);
}

await mkdir(path.join(ROOT, 'results'), { recursive: true });
await writeFile(path.join(ROOT, 'results', 'results-android.json'), JSON.stringify({ date: new Date().toISOString(), results }, null, 1));
const failed = results.filter((r) => r.status === 'failed').length;
const skipped = results.filter((r) => r.status === 'skipped').length;
console.log(`\nИтого: ${results.length - failed - skipped} прошло, ${failed} упало, ${skipped} пропущено → results/results-android.json`);
process.exit(failed ? 1 : 0);
